#include <vector>
#include <string>

class Solution {
public:
    int countPrefixSuffixPairs(std::vector<std::string>& words) {
        int ans = 0, n = words.size();
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int li = words[i].size(), lj = words[j].size();
                if (li <= lj && words[j].substr(0, li) == words[i] && words[j].substr(lj - li) == words[i]) {
                    ans++;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int countPrefixSuffixPairs(String[] words) {
        int ans = 0, n = words.length;
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                if (words[j].startsWith(words[i]) && words[j].endsWith(words[i])) {
                    ans++;
                }
            }
        }
        return ans;
    }
}

